// Consulta de preços do Benjamim (EZ). Entrada: {"busca": "heineken lata; coca 2l"}
// Busca de preços: recebe o texto do cliente e devolve os itens da tabela e das ofertas que batem.
function normTxt(s) {
  return ' ' + String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/(\d+)[.,](\d+)\s*(l|lt|litros?)\b/g, (m, a, b) => ' ' + Math.round(parseFloat(a + '.' + b) * 1000) + 'ml ')
    .replace(/(\d+)\s*(l|lt|lts|litros?)\b/g, (m, a) => ' ' + (parseInt(a, 10) * 1000) + 'ml ')
    .replace(/(\d+)\s*ml\b/g, ' $1ml ')
    .replace(/(\d+)\s*(kg|g)\b/g, ' $1$2 ')
    .replace(/[^a-z0-9]+/g, ' ') + ' ';
}
const SINONIMOS = [
  [/\blitrao\b|\blitr[aã]o\b/g, ' 1000ml '], [/\bcoca\b/g, ' coca cola '], [/\bcocacola\b/g, ' coca cola '], [/\bref(ri|rigerante)?\b/g, ' refri '],
  [/\bcerv(eja)?\b/g, ' cerveja '], [/\bln\b|\blong\s*neck\b|\blongneck\b/g, ' long '], [/\blt\b|\blatinha\b/g, ' lata '],
  [/\bgarrafa\b|\bgarrafinha\b/g, ' vd '], [/\bvidro\b/g, ' vd '], [/\bagua\s*de\s*coco\b/g, ' coco '],
  [/\bwhisky\b|\buisque\b|\bwiski\b/g, ' whisky '], [/\benergetico\b/g, ' energetico '], [/\bcaixas?\b|\bcx\b|\bcxs\b/g, ' '],
  [/\bfardos?\b|\bpacotes?\b|\bpcts?\b|\bunidades?\b|\bund?\b/g, ' ']
];
const IGNORAR = new Set(['de', 'da', 'do', 'com', 'sem', 'e', 'a', 'o', 'pra', 'para', 'quero', 'preco', 'valor', 'qual', 'quanto', 'ta', 'esta', 'tem', 'cerveja', 'refri', 'pet', 'lata']);
function tokens(s) {
  let t = normTxt(s);
  for (const [re, sub] of SINONIMOS) t = t.replace(re, sub);
  return t.split(' ').filter(Boolean);
}
function pontua(qTok, itemTok) {
  const set = new Set(itemTok);
  let hit = 0, peso = 0, volQ = qTok.filter(t => /^\d+(ml|kg|g)$/.test(t)), volOk = true;
  for (const t of qTok) {
    const w = IGNORAR.has(t) ? 0.3 : (/^\d/.test(t) ? 1.5 : 1);
    peso += w;
    if (set.has(t) || (t.length >= 4 && itemTok.some(x => x.startsWith(t) || (x.length >= 4 && t.startsWith(x))))) hit += w;
  }
  if (volQ.length && !volQ.some(v => set.has(v))) volOk = false;
  if (!peso) return 0;
  let s = hit / peso;
  if (!volOk) s *= 0.4; // volume pedido diferente do item
  return s;
}
function hojeBR() {
  const d = new Date(Date.now() - 3 * 3600 * 1000); return d.toISOString().slice(0, 10);
}
function dataBR(s) { const m = String(s || '').match(/(\d{2})\/(\d{2})\/(\d{4})/); return m ? `${m[3]}-${m[2]}-${m[1]}` : ''; }
function buscarPrecos(busca, tabela, ofertas, opts = {}) {
  const limite = opts.limite || 5;
  const termos = String(busca || '').split(/[;\n]|,(?!\d)|\s+e\s+(?=\D)/i).map(s => s.trim()).filter(s => s.length >= 2);
  const hoje = hojeBR();
  const ofIni = dataBR(ofertas && ofertas.validade && ofertas.validade.inicio), ofFim = dataBR(ofertas && ofertas.validade && ofertas.validade.fim);
  const ofertasVigentes = !!ofFim && hoje <= ofFim && (!ofIni || hoje >= ofIni);
  const tabTok = (tabela.itens || []).map(it => tokens(it.nome + ' ' + it.embalagem));
  const ofTok = (ofertas.itens || []).map(it => tokens(it.produto + ' ' + it.variacoes));
  const resultados = [], naoEncontrados = [];
  for (const termo of termos) {
    const q = tokens(termo); if (!q.length) continue;
    const t = (tabela.itens || []).map((it, i) => ({ it, s: pontua(q, tabTok[i]) })).filter(x => x.s >= 0.75).sort((a, b) => b.s - a.s).slice(0, limite);
    const o = ofertasVigentes ? (ofertas.itens || []).map((it, i) => ({ it, s: pontua(q, ofTok[i]) })).filter(x => x.s >= 0.75).sort((a, b) => b.s - a.s).slice(0, 3) : [];
    if (!t.length && !o.length) { naoEncontrados.push(termo); continue; }
    resultados.push({
      busca: termo,
      tabela: t.map(x => ({ codigo: x.it.codigo, nome: x.it.nome, unidade: x.it.unidade, embalagem: x.it.embalagem, preco: x.it.preco })),
      ofertas: o.map(x => ({ produto: x.it.produto, variacoes: x.it.variacoes, preco_oferta: x.it.preco_oferta, faixas: x.it.faixas.map(f => ({ condicao: f.condicao, preco: f.preco })) }))
    });
  }
  return {
    ok: true,
    hoje,
    ofertas_validade: ofertas && ofertas.validade ? `${ofertas.validade.inicio} a ${ofertas.validade.fim}` : '',
    ofertas_vigentes: ofertasVigentes,
    tabela_validade: tabela.validade || '',
    regras: 'Preços por unidade/embalagem descrita. Oferta vale dentro da validade e enquanto durar o estoque, só à vista (dinheiro ou Pix). Faixa "acima de X" só vale se a quantidade do cliente passar de X. Se o item não aparecer, é preço a confirmar pelo vendedor.',
    resultados,
    nao_encontrados: naoEncontrados
  };
}

// Tabela e ofertas vêm do portal (nó "Dados do portal"). Quem lê o PDF e a planilha agora é o portal.
const dados = $('Dados do portal').first().json || {};
const tabela = dados.tabela && dados.tabela.itens ? dados.tabela : { itens: [] };
const ofertas = dados.ofertas && dados.ofertas.itens ? dados.ofertas : { itens: [] };
const j0 = $('Consulta de preços (EZ)').first().json || {};
let body = j0.body || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { busca: body }; } }
if (!body.busca && j0.query && j0.query.busca) body = { busca: j0.query.busca };
const busca = body.busca || body.produtos || body.itens || body.query || '';
const texto = Array.isArray(busca) ? busca.map(b => typeof b === 'string' ? b : (b.produto || b.nome || '')).join('; ') : String(busca);
const out = buscarPrecos(texto, tabela, ofertas);
out.tabela_atualizada_em = dados.tabela_atualizada_em || '';
out.ofertas_atualizadas_em = dados.ofertas_atualizadas_em || '';
if (!tabela.itens.length) { out.ok = false; out.erro = 'Preços indisponíveis agora. Diga ao cliente que o vendedor confirma o preço.'; }
else if (!texto.trim()) { out.ok = false; out.erro = 'Mande o campo "busca" com os produtos separados por ponto e vírgula.'; }
return [{ json: out }];
